-- wave117_almanac.sql (PHASE-11d, 2026-10-28). NOT APPLIED: emci applies it himself, after
-- wave115 and wave116 (Quests). It MUST be applied before ALMANAC_PICK_CUTOVER (2027-02-01):
-- until then the phone keeps the 64-pick rotation and nothing breaks, but from the cutover a
-- phone on the new bundle asks for p66+ picks that only this migration adds (PHASE-27 gate).
-- The community bar stays hidden until daily_pick_event_total answers. The cutover date is
-- written twice below; changing it after this is applied needs a new migration.
--
-- 1. Today's Pick grows from 64 to 368 picks (16 traits x 23, red team H2). The 304 new rows
--    are appended at positions 64..367 (ids p66..p369; ids are forever, nothing is renumbered).
-- 2. Cutover (red team H3): daily_pick_position keeps the 64 rotation before 2027-02-01 and
--    runs the 368 rotation from it. For 14 days from the cutover answer_daily_pick also
--    accepts the 64-rotation pick for that day, so a phone still on the old bundle keeps
--    working. The date is a PLACEHOLDER (>= 14 days after the planned OTA); emci confirms it
--    at PHASE-27, and the app (src/lib/daily-pick/bank.ts ALMANAC_PICK_CUTOVER) must match.
-- 3. Seasonal peak Picks (ev-<event>-<v>): kept in daily_pick_pool so answers can point at
--    them (daily_pick_answers.pick_id references the pool), parked at positions 2000+ so no
--    rotation reaches them, with no axis: answering one moves no trait. On a peak day the
--    override row names one, and answer_daily_pick accepts it as well as the rotation pick.
--    GLOBAL events only (red team M5): the shared Pick is the same for everyone, so a regional
--    or cultural event never gets an override row (the table's check lists the four).
-- 4. daily_pick_event_total: how many answered an event's peak Picks in a year. Totals only,
--    no per-user rows, nothing under 20 answers (same floor as daily_pick_split).
--
-- Schema change to an existing table, no data change: daily_pick_pool's id check now also
-- allows ev-<event>-<n>, and axis may be null only on those rows. No existing row, answer or
-- trait value is updated or deleted.
--
-- The rows below are generated by: npx tsx scripts/gen-wave82-picks.ts --wave117
-- (pinned by check:daily-pick, with both rotations and the cutover date).

-- 1. The pool takes event Picks ------------------------------------------------

alter table public.daily_pick_pool drop constraint daily_pick_pool_id_check;
alter table public.daily_pick_pool add constraint daily_pick_pool_id_check
  check (id ~ '^p[0-9]{2,3}$' or id ~ '^ev-[a-z_]+-[0-9]+$');
alter table public.daily_pick_pool alter column axis drop not null;
alter table public.daily_pick_pool add constraint daily_pick_pool_axis_kind
  check ((id ~ '^p[0-9]') = (axis is not null));

-- 2. Peak-day overrides (global events only) -----------------------------------
-- Same shape as the pool: every signed-in account can read it, nobody writes it.

create table public.daily_pick_event_override (
  ymd date primary key,
  pick_id text not null references public.daily_pick_pool(id),
  event_id text not null check (event_id in ('new_year', 'valentines', 'halloween', 'christmas')),
  created_at timestamptz not null default now(),
  check (pick_id like 'ev-' || event_id || '-%')
);

create index daily_pick_event_override_event_idx on public.daily_pick_event_override (event_id, ymd);

alter table public.daily_pick_event_override enable row level security;

create policy daily_pick_event_override_select_auth on public.daily_pick_event_override
  for select to authenticated
  using (true);

grant select on public.daily_pick_event_override to authenticated;
revoke insert, update, delete on public.daily_pick_event_override from public, anon, authenticated;
revoke all on public.daily_pick_event_override from anon;

-- 3. The rows (generated from src/lib/daily-pick/bank.ts) ----------------------

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (ymd) do nothing;

-- 4. Which pick a date gets: same rule as pickIndexForYmd (bank.ts) -------------
-- 64 rotation: slot = (n % 16) * 4 + n / 16 over n = day % 64 (wave82, unchanged).
-- 368 rotation: slot = (n % 16) * 23 + n / 16 over n = day % 368; trait t's slot k is its
-- wave82 pick (t * 4 + k) for k < 4, else its appended pick (64 + t * 19 + k - 4).
-- Both put trait day % 16 on a day, so the same trait never comes two days running.

create function public.daily_pick_legacy_position(p_ymd date)
returns int
language sql
immutable
set search_path = public
as $$
  select ((((p_ymd - date '2026-01-01') % 64) + 64) % 64 % 16) * 4
       + ((((p_ymd - date '2026-01-01') % 64) + 64) % 64 / 16);
$$;

create or replace function public.daily_pick_position(p_ymd date)
returns int
language sql
immutable
set search_path = public
as $$
  select case
    when p_ymd < date '2027-02-01' then public.daily_pick_legacy_position(p_ymd)
    when s.n / 16 < 4 then (s.n % 16) * 4 + s.n / 16
    else 64 + (s.n % 16) * 19 + (s.n / 16 - 4)
  end
  from (select (((p_ymd - date '2026-01-01') % 368) + 368) % 368 as n) s;
$$;

-- 5. Answer it: the rotation pick, the 64-rotation pick for 14 days from the cutover, or the
--    day's override. Otherwise wave101's copy word for word, plus: an event Pick (no axis)
--    is saved but moves no trait.

create or replace function public.answer_daily_pick(p_ymd date, p_pick_id text, p_option_index int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  uid uuid := auth.uid();
  p record;
  v_opt jsonb;
  v_value double precision;
  v_count int;
  v_mode text;
  v_prev record;
begin
  perform public.require_adult();  -- wave101: 18+ only (docs/under18-server.md)
  if uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  -- A local date: today somewhere on Earth, never a past or future day.
  if p_ymd is null
     or p_ymd < (timezone('utc', now()))::date - 1
     or p_ymd > (timezone('utc', now()))::date + 1 then
    raise exception 'not today' using errcode = '22023';
  end if;
  select * into p from public.daily_pick_pool where id = p_pick_id;
  if not found or not (
       p.position = public.daily_pick_position(p_ymd)
       or (p_ymd < date '2027-02-01' + 14 and p.position = public.daily_pick_legacy_position(p_ymd))
       or exists (select 1 from public.daily_pick_event_override o where o.ymd = p_ymd and o.pick_id = p.id)
     ) then
    raise exception 'not the pick for that day' using errcode = '22023';
  end if;
  if p_option_index is null or p_option_index not in (0, 1) then
    raise exception 'invalid option' using errcode = '22023';
  end if;

  perform 1 from public.me where id = uid for update;

  -- One answer a day: a second tap returns the first answer unchanged.
  select * into v_prev from public.daily_pick_answers where user_id = uid and ymd = p_ymd;
  if found then
    return jsonb_build_object('option_index', v_prev.option_index, 'counted', v_prev.counted, 'already', true);
  end if;

  -- An event Pick has no trait: save the answer, move nothing.
  if p.axis is null then
      values (uid, p_ymd, p_pick_id, p_option_index, false);
    return jsonb_build_object('option_index', p_option_index, 'counted', false, 'already', false);
  end if;

  v_opt := p.options -> p_option_index;
  v_value := (v_opt ->> 'value')::double precision;

  select coalesce(max(answer_count), 0) into v_count
    from public.trait_tracks where user_id = uid and axis = p.axis and track = 'report';
  v_mode := case when v_count >= 3 then 'answer' else 'direct' end;

  perform public._trait_write(uid, p.axis, 'self_situation', v_value, v_mode);
    values (uid, p_ymd, p_pick_id, p_option_index, v_mode = 'answer');

  return jsonb_build_object('option_index', p_option_index, 'counted', v_mode = 'answer', 'already', false);
end;
$$;
revoke all on function public.answer_daily_pick(date,text,integer) from public, anon;
grant execute on function public.answer_daily_pick(date,text,integer) to authenticated;

-- 6. Community counter (totals only; copies daily_pick_split's pattern) -------------
-- How many answered this event's peak Picks in this year. Never who, never which answer,
-- nothing under 20. No "people like you" (D6).

create function public.daily_pick_event_total(p_event_id text, p_year int)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  uid uuid := auth.uid();
  v_total int;
begin
  perform public.require_adult();  -- wave101: 18+ only (docs/under18-server.md)
  if uid is null then
    raise exception 'not authenticated' using errcode = '28000';
  end if;
  if p_event_id is null or p_year is null or p_year < 2026 or p_year > 2100 then
    return null;
  end if;
  select count(*) into v_total
    from public.daily_pick_answers a
    join public.daily_pick_event_override o on o.ymd = a.ymd and o.pick_id = a.pick_id
   where o.event_id = p_event_id
     and o.ymd >= make_date(p_year, 1, 1)
     and o.ymd < make_date(p_year + 1, 1, 1);
  if v_total < 20 then
    return null;
  end if;
  return jsonb_build_object('total', v_total);
end;
$$;

revoke all on function public.daily_pick_event_total(text, int) from public, anon;
grant execute on function public.daily_pick_event_total(text, int) to authenticated;
